<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('rewards.view');$id=(int)input('id');if(is_post()){require_permission('rewards.approve');verify_csrf();try{decide_reward($id,strtoupper((string)input('action')),trim((string)input('reason'))?:null,(int)admin()['id']);flash('success','Reward decision saved atomically.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/rewards/view.php?id='.$id);}$s=db()->prepare('SELECT r.*,u.name user_name,u.mobile,u.status user_status,h.title hunt_title,hs.latitude,hs.longitude,hs.distance_meters,hs.allowed_radius_meters,hs.risk_level,hs.device_id,hs.ip_address,hs.scanned_at,w.transaction_id FROM rewards r JOIN users u ON u.id=r.user_id JOIN hunts h ON h.id=r.hunt_id JOIN hunt_scans hs ON hs.id=r.scan_id LEFT JOIN wallet_transactions w ON w.id=r.wallet_transaction_id WHERE r.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Reward not found');}$attempts=db()->prepare('SELECT challenge_type,challenge_id,successful,attempted_at FROM hunt_challenge_attempts WHERE scan_id=? ORDER BY id');$attempts->execute([$r['scan_id']]);$pageTitle='Reward '.$r['reward_id'];$pageSubtitle='Server-generated reward and complete scan evidence';require APP_ROOT.'/includes/header.php';?><div class="grid detail-grid"><section class="panel"><h2>Reward</h2><?php foreach(['User'=>$r['user_name'].' · '.$r['mobile'],'Hunt'=>$r['hunt_title'],'Amount'=>money($r['amount']),'Status'=>$r['status'],'Wallet transaction'=>$r['transaction_id']??'—','Rejection reason'=>$r['rejection_reason']??'—'] as $k=>$v):?><div class="kv"><span><?=e($k)?></span><strong><?=e($v)?></strong></div><?php endforeach?></section><section class="panel"><h2>Scan evidence</h2><?php foreach(['Coordinates'=>$r['latitude'].', '.$r['longitude'],'Distance'=>$r['distance_meters'].' / '.$r['allowed_radius_meters'].' m','Risk'=>$r['risk_level'],'Device'=>$r['device_id'],'IP'=>$r['ip_address'],'Scanned'=>$r['scanned_at']] as $k=>$v):?><div class="kv"><span><?=e($k)?></span><strong><?=e($v)?></strong></div><?php endforeach?></section></div><section class="panel"><h2>Challenge attempts</h2><div class="table-wrap"><table><thead><tr><th>Type</th><th>Challenge</th><th>Result</th><th>Time</th></tr></thead><tbody><?php foreach($attempts->fetchAll() as $a):?><tr><td><?=e($a['challenge_type'])?></td><td>#<?=e($a['challenge_id'])?></td><td><?=e($a['successful']?'SUCCESS':'FAILED')?></td><td><?=e($a['attempted_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php if($r['status']==='PENDING'&&can('rewards.approve')):?><section class="panel"><h2>Decision</h2><form method="post" class="filters" data-confirm="This decision is final. Continue?"><?=csrf_field()?><select name="action"><option>APPROVED</option><option>REJECTED</option></select><input name="reason" maxlength="500" placeholder="Reason (required for rejection)"><button class="btn">Save decision</button></form></section><?php endif?><?php require APP_ROOT.'/includes/footer.php';
